// Join a directed voice room by number (1-100, supports decimals like 89.3)
app.post('/api/directed/join', requireAuth, async (req, res) => {
  try {
    const { number } = req.body;
    if (number === undefined || number === null || number === '') {
      return res.status(400).json({ error: 'الرجاء إدخال رقم' });
    }
    const n = parseFloat(number);
    if (isNaN(n) || n < 1 || n > 100) {
      return res.status(400).json({ error: 'يجب أن يكون الرقم بين 1 و 100' });
    }

    // Only members with the الأفراد role can join directed voice
    const hasRole = await bot.hasTargetRole(req.session.user.id);
    if (!hasRole) {
      return res.status(403).json({ error: 'ليس لديك صلاحية الدخول الموجه' });
    }

    // Move the member into the directed voice channel
    const result = await bot.joinDirectedVoice(req.session.user.id, n);

    // Record the directed entry in db
    db.setDirected({
      memberId: req.session.user.id,
      memberName: req.session.user.global_name || req.session.user.username,
      number: String(n),
    });

    res.json({ success: true, number: n, channelName: result.channelName });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

