// List all sector members (from Discord role + db merge)
app.get('/api/admin/members', requireAdmin, async (req, res) => {
  try {
    // Refresh the bot cache to get the current members with the LSPD role
    await bot.refresh();
    const roleMembers = bot.getMembers(); // members with target role in Discord
    const dbMembers = db.getMembers();    // db records (rank, warnings)
    const warnings = db.getWarnings();

    // Merge: use Discord role members as the source of truth, fall back to db for rank
    const merged = roleMembers.map((m) => {
      const dbRec = dbMembers.find((x) => String(x.id) === String(m.id));
      const w = warnings.filter((x) => String(x.member_id) === String(m.id));
      return {
        id: String(m.id),
        name: m.displayName || m.username || (dbRec ? dbRec.name : ''),
        rank: dbRec ? dbRec.rank : 'جندي',
        rankIndex: dbRec ? dbRec.rankIndex : 0,
        avatar: m.avatar || '',
        isOnline: m.isOnline,
        added_by: dbRec ? dbRec.added_by : '',
        warnings: w,
        warningCount: w.length,
        maxWarnings: db.MAX_WARNINGS,
        threatened: w.length >= db.MAX_WARNINGS - 1,
        removeReady: w.length >= db.MAX_WARNINGS,
      };
    });

    // Also include db members that might not have the role fetched yet
    const roleIds = new Set(roleMembers.map((m) => String(m.id)));
    dbMembers.forEach((m) => {
      if (!roleIds.has(String(m.id))) {
        const w = warnings.filter((x) => String(x.member_id) === String(m.id));
        merged.push({
          id: String(m.id),
          name: m.name,
          rank: m.rank,
          rankIndex: m.rankIndex,
          avatar: '',
          isOnline: false,
          added_by: m.added_by,
          warnings: w,
          warningCount: w.length,
          maxWarnings: db.MAX_WARNINGS,
          threatened: w.length >= db.MAX_WARNINGS - 1,
          removeReady: w.length >= db.MAX_WARNINGS,
        });
      }
    });

    res.json({ members: merged });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

