// Add a member to the sector (assign role in Discord + add to db)
app.post('/api/admin/members', requireAdmin, async (req, res) => {
  try {
    const { id, name, rank } = req.body;
    if (!id || !name || !rank) return res.status(400).json({ error: 'ID, name, and rank are required' });

    // Give the sector role in Discord
    try {
      await bot.addMemberToSector(id);
    } catch (err) {
      // If the member isn't in the server, still add them to db? Warn but continue.
      return res.status(400).json({ error: 'تعذر إضافة العضو في السيرفر: ' + err.message });
    }

    const result = db.addMember({ id, name, rank, addedBy: req.session.user.username });
    if (!result.success && result.error === 'exists') {
      return res.status(400).json({ error: 'العضو موجود بالفعل في القطاع' });
    }
    logAction(req, 'إضافة فرد ➕', name, id, 'الرتبة: ' + rank);
    res.json({ member: result.member });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

