// Helper: ensure a member record exists in db (auto-add from Discord role if missing)
async function ensureMemberInDb(id) {
  const existing = db.getMembers().find((m) => String(m.id) === String(id));
  if (existing) return existing;
  // Try to get name from bot cache
  const botMember = bot.getMembers().find((m) => String(m.id) === String(id));
  const name = botMember ? (botMember.displayName || botMember.username) : String(id);
  const result = db.addMember({ id, name, rank: 'جندي', addedBy: 'system' });
  return result.success ? result.member : null;
}

