// ---- Start ----
function start() {
  if (!CLIENT_ID || !CLIENT_SECRET) {
    console.error('❌ Missing Discord credentials. Set DISCORD_CLIENT_ID and DISCORD_CLIENT_SECRET in the environment.');
    process.exit(1);
  }

  // Login the bot (optional but needed for presence tracking)
  if (process.env.DISCORD_BOT_TOKEN) {
    bot.client.login(process.env.DISCORD_BOT_TOKEN).then(() => {
      console.log('✅ Presence bot connected');
    }).catch((err) => {
      console.error('❌ Bot login failed:', err.message);
    });
  } else {
    console.warn('⚙️ DISCORD_BOT_TOKEN not set - presence tracking disabled');
  }

  app.listen(PORT, () => {
    console.log(`🚀 LSPD server running at http://localhost:${PORT}`);
    console.log(`   OAuth login URL: http://localhost:${PORT}/api/auth/discord`);
  });
}

start();

